tipping.donation_custom_js:
$( document ).ready(function() {  
  var alertImage = document.getElementById("alert-image");
  var alertText = document.getElementById("alert-type");
  var alertMessage = document.getElementById("alertMessage");
  var alertName = document.getElementById("alertMessage");
  var alertInner = document.getElementById("typeInner");
  var alertMessageInner = document.getElementById("alertMessageInner");

  const maxFontSize = 6;
  const fontMultiplier = 5;
  const maxTextLength = 26;
  const topVariation = 45;

  alertText.style.zIndex = "2";
  alertName.style.zIndex = "3";
  alertMessageInner.style.zIndex = "1";
  alertImage.style.zIndex = "-1";
  //InitFontSize();
  setTimeout(function(){splitUpText();}, 400);
  setTimeout(function(){fadeInMessage2();}, 1000);
  setTimeout(function(){fadeOutMessages();}, 4500);

  function InitFontSize()
  {
     var length =  alertMessageInner.innerText.length;
    let newFontSize = maxFontSize - ((length/maxTextLength) * fontMultiplier);
    alertMessageInner.style.opacity = "1";
    alertMessageInner.style.fontSize = newFontSize + "vw";
  }

  function splitUpText()
  {
    alertInner.style.opacity = "1";
    var textArray = alertText.innerText.split("");
    let alertTextWidth = alertInner.offsetWidth + 1;
    alertInner.innerText = "";
    alertInner.style.width = alertTextWidth + 1;

    for(i = 0; i < textArray.length; i++){
      let newLetter = document.createElement("span");
      newLetter.style.opacity = "0";
      newLetter.innerText = textArray[i];
      setTimeout(function(){
        newLetter.classList.add("alert-type-animation"); 
        newLetter.style.opacity = "1";
      }, i * 50);
      alertInner.appendChild(newLetter);
    }
  }

  function SetInnerTop()
  {
    alertInner.style.top ="0";
  }

  function fadeInMessage2()
  {
    alertMessageInner.style.animation = "reveal 0.5s ease-out";
    alertMessageInner.addEventListener("webkitAnimationEnd", SetInnerLeft,false);
         alertMessageInner.addEventListener("animationend", SetInnerLeft,false);
      alertMessageInner.addEventListener("oanimationend", SetInnerLeft,false);    
  }

  function SetInnerLeft()
  {
    alertMessageInner.style.clipPath = "polygon(0 0, 100% 0, 100% 100%, 0% 100%)";
  }

  function fadeOutMessages()
    {
    alertMessageInner.style.animation = "hide 0.5s ease-out";
    alertInner.style.animation = "fadeOut 0.5s ease-out";

    alertMessageInner.addEventListener("webkitAnimationEnd", SetMessageEnd,false);
         alertMessageInner.addEventListener("animationend", SetMessageEnd,false);
      alertMessageInner.addEventListener("oanimationend", SetMessageEnd,false);    

    alertInner.addEventListener("webkitAnimationEnd", SetInnerEnd,false);
         alertInner.addEventListener("animationend", SetInnerEnd,false);
      alertInner.addEventListener("oanimationend", SetInnerEnd,false);    
  }

  function SetInnerEnd()
  {
    alertInner.style.top = "100";
    alertInner.style.opacity = "0";
  }

  function SetMessageEnd()
    {
    alertMessageInner.style.clipPath = "polygon(0 0, 0 0, 0 100%, 0% 100%)";
  }
});

tipping.donation_custom_css:
@import url('https://fonts.googleapis.com/css2?family=Exo:wght@700&display=swap');

body,
html {
    height: 100%;
    width: 100%;
    overflow: hidden;	
    font-family: 'Exo', sans-serif;
    text-transform: uppercase;
}

#wrap {
    position: relative;
    height: 100%;
    width: 100%;
}
#alert-box {
    height: 100%;
    width: 100%;
    position: absolute;
}
#alert-box.hidden,
.hidden {
    opacity: 0;
}

#alertGivenMessage {
    text-align: center;
    color: white;
}

#alert-image {
    position: relative;
}

#alert-image video {
    width: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

#alert-image {
  z-index: -2;
  position: relative;
}

.alert-box-wrapper{
  width: 100%;
  height: 100%;
  top: 0;
  position: absolute;
}

.alert-box-inner-wrapper
{
  text-transform: Uppercase;
  width: 100vw;
  height: 56.25vw;
  display: inline-block;
  text-align: center;
}

.alert-box-inner-wrapper-alt
{
  text-transform: Uppercase;
  width: 100vw;
  height: 56.25vw;
  text-align: center;
  display: inline-block;
}

#alert-type
{
  margin-top: 41.3vw;
  z-index: 3;
}

#typeInner
{
  letter-spacing: .2vw;
  font-weight: bold;
  color: white;
  font-size: 2.8vw;
  position: relative;
  opacity: 0;
}

#alertMessage{
  margin-top: 48vw;
  display: inline-block;
}

#alertMessageInner
{
  color: white;
  font-size: 4vw;
  position: relative;
  clip-path: polygon(0 0, 0% 0, 0% 100%, 0% 100%);
}

.alert-type-animation
{
  animation: popIn 0.2s ease-out 0s 1;
  position: relative;
}

@keyframes fadeOut
{
  from{opacity: 100;}
  to{opacity: 0;}
}

@keyframes popIn
{
  from{top: 25;}
  to{top: 0;}
}

@keyframes popOut
{
  from{top: 0;}
  to{top: 100;}
}

@keyframes reveal
{
  to{clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);}
}

@keyframes hide
{
  to{clip-path: polygon(0 0, 0 0, 0 100%, 0% 100%);}
}

merch.merch_custom_css:
.widget-AlertBox {
    position: relative;
}
body,
html {
    height: 100%;
    width: 100%;
    overflow: hidden;
}
#wrap {
    position: relative;
    height: 100%;
    width: 100%;
}
#alert-box {
    height: 100%;
    width: 100%;
    position: absolute;
}
#alert-box.hidden,
.hidden {
    opacity: 0;
}
#alert-text {
    padding: 20px;
    text-shadow: 0px 0px 1px #000, 0px 0px 2px #000, 0px 0px 3px #000, 0px 0px 4px #000, 0px 0px 5px #000;
}
#alert-message,
#alert-user-message {
    text-align: center;
}
#alert-user-message img {
    vertical-align: middle;
    height: 1em;
}
#alert-image {
    position: relative;
}
#alert-image video {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}
#alert-message > span > span {
    display: inline-block;
}
#alert-image {
    z-index: 6;
    position: relative;
}
#alert-text {
    z-index: 6;
    position: relative;
}
#alert-text-wrap {
    z-index: 6;
    position: relative;
}

